import { AriaLiveAnnouncer } from '@fluentui/react-components';

const CharacterCount = () => {
  const [count, setCount] = React.useState(0);
  const announceId = useId('charCount');
  const { typingAnnounce, inputRef } = useTypingAnnounce();

  const onInput = (ev) => {
    const charCount = ev.target.textContent?.length ?? 0;
    setCount(charCount);
    const message = charCountMessage(charCount);
    if (message) {
      typingAnnounce(message, { batchId: announceId });
    }
  };

  return (
    <AriaLiveAnnouncer>
      <Field label="Enter text">
        <span contentEditable ref={inputRef} onInput={onInput} />
      </Field>
    </AriaLiveAnnouncer>
  );
};

import { AriaLiveAnnouncer } from '@fluentui/react-components';

const SearchResults = () => {
  const [results, setResults] = React.useState([]);
  const announceId = useId('filter');
  const { typingAnnounce, inputRef } = useTypingAnnounce();

  const onChange = (_, data) => {
    const searchString = data.value.trim().toLowerCase();
    const filteredItems = searchString.length ? sampleItems.filter(item => item.includes(searchString)) : [];
    setResults(filteredItems);
    const message = resultsMessage(filteredItems.length);
    typingAnnounce(message, { batchId: announceId });
  };

  return (
    <AriaLiveAnnouncer>
      <Field label="Search">
        <Input onChange={onChange} ref={inputRef} />
      </Field>
      {results.length ? <ul>{results.map(item => <li key={item}>{item}</li>)}</ul> : null}
    </AriaLiveAnnouncer>
  );
};

