import { CalendarCompat } from '@fluentui/react-calendar-compat';

const CalendarDateBoundaries = () => {
  const today = new Date();
  const minDate = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());
  const maxDate = new Date(today.getFullYear() + 1, today.getMonth(), today.getDate());

  const [selectedDate, setSelectedDate] = React.useState<Date>();

  const onSelectDate = (date: Date) => setSelectedDate(date);

  return (
    <CalendarCompat
      highlightSelectedMonth
      minDate={minDate}
      maxDate={maxDate}
      onSelectDate={onSelectDate}
      value={selectedDate}
    />
  );
};

