const ControlledDatePicker = () => {
  const [selectedDate, setSelectedDate] = React.useState<Date | null>(null);

  return (
    <DatepickerCompat
      value={selectedDate}
      onSelectDate={setSelectedDate}
      placeholder="Select a date..."
    />
