};

import { DatepickerCompat } from '@fluentui/react-datepicker-compat';

const CustomDateFormatting = () => {
  const formatDate = (date?: Date) => date ? date.toLocaleDateString() : '';
  const parseDateFromString = (dateStr: string) => new Date(dateStr);

  return (
    <DatepickerCompat
      formatDate={formatDate}
      parseDateFromString={parseDateFromString}
      allowTextInput
      placeholder="Select a date..."
    />
  );
};

