        size={size}
        {...restoreFocusSourceAttributes}
        position="end"
        open={open}
        onOpenChange={(_, state) => setOpen(state.open)}
      >
        <DrawerHeader>
          <DrawerHeaderTitle
            action={
              <Button
                appearance="subtle"
                aria-label="Close"
                icon={<Dismiss24Regular />}
                onClick={() => setOpen(false)}
              />
