type TableSelectableRowProps = {
  toggleRow: TableSelectionState['toggleRow'];
  item: Item;
  selected: boolean;
  appearance: TableRowProps['appearance'];
  rowId: TableRowId;
};

const TableSelectableRow: React.FC<TableSelectableRowProps> = props => {
