          setUnmounted(status === 'unmounted');
          setPaused(false);
        },
      },
    );
    setUnmounted(false);
  };

  const toggle = () => {
    if (paused) {
      playToast(toastId);
      setPaused(false);
    } else {
      pauseToast(toastId);
      setPaused(true);
    }
  };

  return (
    <>
      <Toaster toasterId={toasterId} />
      <Button disabledFocusable={!unmounted} onClick={notify}>
        Make toast
      </Button>
      <ToggleButton
        icon={paused ? <PlayFilled /> : <PauseFilled />}
        disabledFocusable={unmounted}
        onClick={toggle}
