import { Tree } from '@fluentui/react-components';

const LazyLoadingTree = () => {
  const [items, setItems] = React.useState([]);
  const loadItems = () => {
    // Fetch or generate items
    setItems([...items, { value: 'new-item', content: 'New Item' }]);
  };

  return (
    <Tree onOpenChange={loadItems} aria-label="Lazy Loading Tree">
      {items.map(item => (
        <TreeItem key={item.value} value={item.value} itemType="leaf">
          <TreeItemLayout>{item.content}</TreeItemLayout>
        </TreeItem>
      ))}
    </Tree>
  );
