import React, { useState } from 'react';
import { Input, Button, Field } from '@fluentui/react-components';

const UserRegistrationForm: React.FC = () => {
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [errors, setErrors] = useState<{ username?: string; email?: string }>({});

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    const newErrors: { username?: string; email?: string } = {};
    if (!username) newErrors.username = 'Username is required';
    if (!email) newErrors.email = 'Email is required';
    setErrors(newErrors);
    if (Object.keys(newErrors).length === 0) {
      alert('Form submitted successfully!');
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Field validationState={errors.username ? 'error' : undefined} required size="medium">
        <Input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Enter your username"
          size="medium"
        />
        {errors.username && <span>{errors.username}</span>}
      </Field>
      <Field validationState={errors.email ? 'error' : undefined} required size="medium">
        <Input
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="Enter your email"
          size="medium"
        />
        {errors.email && <span>{errors.email}</span>}
      </Field>
      <Button type="submit" appearance="primary" size="medium">
        Register
      </Button>
    </form>
  );
};

export default UserRegistrationForm;

import React, { useState } from 'react';
import { Input, Button, Field } from '@fluentui/react-components';

const SimpleFormWithValidation: React.FC = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [errors, setErrors] = useState({ name: '', email: '' });

  const validate = () => {
    const newErrors = { name: '', email: '' };
    if (!name) {
      newErrors.name = 'Name is required';
    }
    if (!email) {
      newErrors.email = 'Email is required';
    } else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      newErrors.email = 'Email is invalid';
    }
    setErrors(newErrors);
    return !newErrors.name && !newErrors.email;
  };

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    if (validate()) {
      // Submit form
      console.log('Form submitted successfully');
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Field validationState={errors.name ? 'error' : 'none'}>
        <Input
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Name"
        />
        {errors.name && <span>{errors.name}</span>}
      </Field>
      <Field validationState={errors.email ? 'error' : 'none'}>
        <Input
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="Email"
        />
        {errors.email && <span>{errors.email}</span>}
      </Field>
      <Button type="submit">Submit</Button>
    </form>
  );
};

export default SimpleFormWithValidation;

