import React, { useState } from 'react';
import { Input, Button, Field } from '@fluentui/react-components';

const ContactForm: React.FC = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    if (name && email) {
      setIsSubmitted(true);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Field validationState={name ? 'valid' : 'invalid'} required size="medium">
        <Input
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Enter your name"
          size="medium"
          appearance="outline"
        />
      </Field>
      <Field validationState={email ? 'valid' : 'invalid'} required size="medium">
        <Input
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="Enter your email"
          size="medium"
          appearance="outline"
        />
      </Field>
      <Button type="submit" appearance="primary" disabled={!name || !email}>
        Submit
      </Button>
      {isSubmitted && <div>Form submitted successfully!</div>}
    </form>
  );
};

export default ContactForm;

import React, { useState } from 'react';
import { Button, Input, Field, Spinner } from '@fluentui/react-components';

const FormWithLoadingState: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [inputValue, setInputValue] = useState('');

  const handleSubmit = async () => {
    setLoading(true);
    // Simulate an API call
    await new Promise(resolve => setTimeout(resolve, 2000));
    setLoading(false);
  };

  return (
    <div>
      <Field>
        <Input
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          disabled={loading}
        />
      </Field>
      <Button onClick={handleSubmit} disabled={loading} appearance="primary">
        {loading ? <Spinner size="small" /> : 'Submit'}
      </Button>
    </div>
  );
};

export default FormWithLoadingState;

import React, { useState } from 'react';
import { Input, Field, Button } from '@fluentui/react-components';

const ErrorHandlingForm: React.FC = () => {
  const [value, setValue] = useState('');
  const [error, setError] = useState('');

  const validateInput = (inputValue: string) => {
    if (inputValue.trim() === '') {
      setError('This field is required.');
    } else {
      setError('');
    }
  };

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = event.target.value;
    setValue(newValue);
    validateInput(newValue);
  };

  const handleSubmit = () => {
    validateInput(value);
    if (error === '') {
      alert('Form submitted successfully!');
    }
  };

  return (
    <div>
      <Field validationState={error ? 'error' : 'success'}>
        <Input value={value} onChange={handleChange} placeholder="Enter text" />
      </Field>
      {error && <div style={{ color: 'red' }}>{error}</div>}
      <Button onClick={handleSubmit} disabled={!!error}>Submit</Button>
    </div>
  );
};

export default ErrorHandlingForm;

